function validateGeneration(entry,overrides={}){
 valid('pipeline-entry.schema.json',entry);
 unique(entry.bindings,x=>[x.role,x.owner,x.instanceId].join('|'),'DUPLICATE_COMPONENT');unique(entry.pluginSelections,x=>[x.kind,x.registrationId,x.serviceInstanceId].join('|'),'AMBIGUOUS_REGISTRATION');unique(entry.deploymentSelections,x=>[x.role,x.consumer,x.deploymentInstanceId].join('|'),'DUPLICATE_DEPLOYMENT');unique(entry.infrastructureSelections,x=>[x.role,x.deploymentInstanceId].join('|'),'DUPLICATE_INFRA');
 const owners=new Map();const obtain=(rel,schema)=>{assert(!rel.includes('..')&&!path.isAbsolute(rel),'OWNER_PATH_ESCAPE');if(!owners.has(rel)){const value=structuredClone(overrides[rel]||read(path.join(stand,rel)));valid(schema,value);owners.set(rel,value);}return owners.get(rel);};
 for(const [owner,rel] of Object.entries(entry.components))obtain('config/'+rel,'provider03/components/'+owner+'.schema.json');
 for(const binding of entry.bindings)assert(owners.get('config/'+entry.components[binding.owner]).profiles[binding.profileId],'MISSING_COMPONENT_PROFILE');
 for(const tuple of entry.pluginSelections){
  const o=obtain('config/'+tuple.ownerPath,'provider03/'+tuple.packageId+'.schema.json');assert(o.packageId===tuple.packageId&&o.registrationId===tuple.registrationId&&o.instanceId===tuple.instanceId,'WRONG_PACKAGE_REGISTRATION_INSTANCE');assert(o.profiles[tuple.profileId],'MISSING_PLUGIN_PROFILE');
  if(tuple.kind==='test-provider')assert(entry.bindings.some(b=>b.role==='buster'&&b.owner==='buster-engine'&&b.instanceId===tuple.serviceInstanceId),'UNKNOWN_BUSTER_SERVICE');else assert(tuple.packageId==='kubeclaw.network-http'&&tuple.serviceInstanceId==='fixture.service.nova-runtime','UNSUPPORTED_NOVA_CONTEXT');
  for(const [id,p] of Object.entries(o.profiles)){if(p.processing.maximumRequestTimeoutMs!==undefined)assert(p.processing.requestTimeoutMs<=p.processing.maximumRequestTimeoutMs,'DEFAULT_EXCEEDS_CEILING:'+tuple.packageId+'/'+id);}
 }
 const chart=obtain('charts/kubeclaw/values.yaml','controller-owner.schema.json');const recovery=obtain('my-values/infra/postgresql-recovery.yaml','recovery02/postgresql-recovery-policy.schema.json');
 for(const [id,p] of Object.entries(chart.profiles)){
  assert(p.profileId===id,'PROFILE_ID_KEY_MISMATCH');const b=p.settings.busterNamespaceBroker;if(!b.enabled)continue;assert(b.defaultTtlSeconds<=b.maxTtlSeconds,'CONTROLLER_TTL_RELATION');
  if(b.controller.readiness.enabled)assert(b.controller.readiness.port>=1&&b.controller.readiness.port<=65535,'PORT_DOMAIN');assert(!p.readonlyBindings.product.enabled||b.controller.readiness.enabled,'PRODUCT_REQUIRES_READY');
 }
 for(const [id,p] of Object.entries(recovery.profiles)){try{recoveryRelations(p.settings);}catch(e){throw Error('RECOVERY_RELATION:'+id+':'+e.message);}}
 const sourceAssociations=[];
 for(const d of entry.deploymentSelections){
  const p=chart.profiles[d.profileId];assert(p,'MISSING_DEPLOYMENT_PROFILE');const b=p.settings.busterNamespaceBroker;
  const find=(owner,instance)=>{const join=entry.bindings.filter(x=>x.owner===owner&&x.instanceId===instance);assert(join.length===1,'MISSING_OR_AMBIGUOUS_COMPONENT_JOIN:'+owner);return owners.get('config/'+entry.components[owner]).profiles[join[0].profileId].settings;};
  const bs=find('buster-engine',d.busterComponentInstanceId),control=find('prism-control',d.controlComponentInstanceId);
  assert(p.role===d.role,'ROLE_PROFILE_MISMATCH');if(b.enabled){assert(p.readonlyBindings.sharedLease.apiGroup===bs.clusterInvokers.shared.leaseApiGroup&&p.readonlyBindings.sharedLease.apiVersion===bs.clusterInvokers.shared.leaseApiVersion,'CMP_GROUP_VERSION_SOURCE_MISMATCH');assert(p.readonlyBindings.product.enabled===control.productAuthority.enabled,'CONTROL_PRODUCT_SOURCE_MISMATCH');assert(p.readonlyBindings.resourceNamePrefix==='agent-'+d.role,'HELPER_RESOURCE_IDENTITY');}
  sourceAssociations.push({kind:'controller',tuple:d,selected:p,projection:'same existing Chart, generated policy/ENV/CRD/RBAC/mount/client bindings proposed only',activation:'MISSING_EXTERNAL_RECEIPTS_AND_IMPLEMENTATION_NOT_AUTHORIZED'});
 }
 for(const d of entry.infrastructureSelections){assert(d.role==='postgresql-recovery','UNSUPPORTED_INFRA_ROLE');assert(recovery.profiles[d.profileId],'MISSING_INFRA_PROFILE');sourceAssociations.push({kind:'recovery',tuple:d,selected:recovery.profiles[d.profileId],activation:'MISSING_AUTHENTIC_DEPLOY_CALLER_SOURCE_IMAGE_TASK_FD10_FD11_AND_SUPERVISOR_RECEIPTS'});}
 return {rootSha256:sha(path.join(stand,'config/pipeline.config.json')),owners:[...owners.keys()],sourceAssociations};
}

function entryErrors(r,documents=componentDocuments){const errors=[];const tuples=r.pluginSelections.filter(t=>t.packageId===owner.packageId);
 if(tuples.length!==5||new Set(tuples.map(t=>t.registrationId)).size!==5)errors.push('missing-or-duplicate-registration');
 if(new Set(tuples.map(t=>t.profileId)).size!==1||new Set(tuples.map(t=>t.instanceId)).size!==1)errors.push('split-one-package-instance-profile');
 if(new Set(tuples.map(t=>t.ownerPath)).size!==1)errors.push('split-one-package-owner-path');
 if(new Set(tuples.map(t=>t.serviceInstanceId)).size!==1)errors.push('split-one-package-service-context');
 for(const t of tuples){if(t.instanceId!==owner.instanceId||t.ownerPath!=='plugins/kubeclaw.security-providers.config.json'||!owner.profiles[t.profileId]||!decls[t.registrationId.split(':')[1]]||t.kind!=='test-provider')errors.push('wrong-package-instance-profile-kind');
 const bindings=r.bindings.filter(b=>b.instanceId===t.serviceInstanceId),engines=bindings.filter(b=>b.owner==='buster-engine'),workers=bindings.filter(b=>b.owner==='worker-core');
 if(!t.serviceInstanceId||engines.length!==1||workers.length!==1) {errors.push('missing-exact-runtime-receiving-closure');continue;}
 const engine=engines[0],worker=workers[0];if(engine.role!=='buster'||worker.role!=='buster')errors.push('wrong-runtime-role');
 if(r.components['buster-engine']!==root.components['buster-engine']||r.components['worker-core']!==root.components['worker-core'])errors.push('wrong-runtime-owner-path');
 const settings=documents['buster-engine']?.profiles[engine.profileId]?.settings,ws=documents['worker-core']?.profiles[worker.profileId];
 if(!settings||!ws){errors.push('missing-runtime-resource-profile');continue;}
 if(!['security-source-A','security-https-source-A'].includes(engine.profileId)||worker.profileId!=='local-A')errors.push('wrong-captured-runtime-context');
 const network=engine.profileId==='security-https-source-A'?assoc.httpsStand:assoc.network;
 if(JSON.stringify(settings.execution.capabilityProviders.networkHttp)!==JSON.stringify(network)||JSON.stringify(settings.execution.capabilityProviders.securityScan)!==JSON.stringify(assoc.securityScan)||JSON.stringify(settings.clusterInvokers.runtimeSecurity)!==JSON.stringify(assoc.runtimeSecurity))errors.push('wrong-captured-native-resource-projection');
 const caps=decls[t.registrationId.split(':')[1]]?.requiredCapabilities??[];if(caps.some(c=>!settings.remotePlanService.allowedCapabilities.includes(c)))errors.push('missing-declared-capability-ceiling');
 }return [...new Set(errors)];}

function rule(value) {
  const item = object(value, 'SECURITY_HEADERS_RULE_INVALID');
  if (typeof item.id !== 'string' || !/^[a-z0-9.-]+$/u.test(item.id) || item.id.length > 128
    || typeof item.header !== 'string' || !/^[a-z0-9-]+$/u.test(item.header) || item.header.length > 128
    || !SEVERITIES.includes(item.severity) || !['present', 'equals', 'contains', 'hsts-min-age'].includes(item.kind)
    || (item.kind !== 'present' && (typeof item.value !== 'string' || item.value.length < 1 || item.value.length > 1024))
    || (item.kind === 'hsts-min-age' && (!/^\d+$/u.test(item.value) || Number(item.value) < 1))) {
    throw new Error('SECURITY_HEADERS_RULE_INVALID');
  }
  return { id: item.id, header: item.header, severity: item.severity, kind: item.kind,
    ...(item.kind === 'present' ? {} : { value: item.value }) };
}

function rules(profileName, overrides) {
  const base = PROFILES[profileName];
  if (!base) throw new Error('SECURITY_HEADERS_PROFILE_INVALID');
  const value = overrides === undefined ? {} : object(overrides, 'SECURITY_HEADERS_RULES_INVALID');
  const remove = value.remove ?? [];
  if (!Array.isArray(remove) || remove.length > 32 || new Set(remove).size !== remove.length
    || remove.some((id) => typeof id !== 'string')) throw new Error('SECURITY_HEADERS_RULES_INVALID');
  const replace = (value.replace ?? []).map(rule); const add = (value.add ?? []).map(rule);
  const replacement = new Map(replace.map((item) => [item.id, item]));
  if (replacement.size !== replace.length || new Set(add.map((item) => item.id)).size !== add.length
    || add.some((item) => base.some((existing) => existing.id === item.id) || replacement.has(item.id))
    || replace.some((item) => !base.some((existing) => existing.id === item.id))) throw new Error('SECURITY_HEADERS_RULES_INVALID');
  const resolved = base.filter((item) => !remove.includes(item.id)).map((item) => replacement.get(item.id) ?? item).concat(add);
  if (resolved.length < 1 || resolved.length > 64 || new Set(resolved.map((item) => item.id)).size !== resolved.length) {
    throw new Error('SECURITY_HEADERS_RULES_INVALID');
  }
  return resolved;
}

export function object(value, code) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error(code);
  return value;
}

function responseHeaderNames(value: unknown): readonly string[] {
  if (value === undefined) return Object.freeze(['content-type']);
  if (!Array.isArray(value) || value.length > 32 || value.some((name) => typeof name !== 'string'
    || !/^[a-z0-9!#$%&'*+.^_`|~-]+$/iu.test(name)
    || (DENIED_HEADERS.has(name.toLowerCase()) && name.toLowerCase() !== 'content-length'))) {
    throw new Error('HTTP_RESPONSE_HEADERS_INVALID');
  }
  return Object.freeze([...new Set(['content-type', ...value.map((name) => name.toLowerCase())])]);
}
